import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"離","description":"周易集解 - 離","frontmatter":{"title":"離","description":"周易集解 - 離"},"headers":[],"relativePath":"classics/jijie/030.md","filePath":"classics/jijie/030.md"}'),l={name:"classics/jijie/030.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="離" tabindex="-1">離 <a class="header-anchor" href="#離" aria-label="Permalink to “離”">​</a></h1><h2 id="離-1" tabindex="-1">離 <a class="header-anchor" href="#離-1" aria-label="Permalink to “離”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>離，利貞，亨。畜牝牛，吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：陷必有所麗，故受之以離。離者，麗也。</p><p>崔憬曰：物極則反。坎雖陷於地，必有所麗於天，而受之以離也。</p><p>虞翻曰：坤二五之乾，與坎旁通。於爻，遯初之五，柔麗中正，故利貞亨。</p><p>虞翻曰：畜，養也。坤為牝牛。乾二五之坤成坎，體頤養象。故畜牝牛吉。俗說皆以離為牝牛，失之矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：離，麗也。日月麗乎天。百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故亨。是以畜牝牛吉也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>荀爽曰：陰麗於陽，相附麗也。亦為別離，以陰隔陽也。離者，火也。託於木，是其附麗也。煙燄飛升，炭灰降滯，是其別離也。</p><p>虞翻曰：乾五之坤成坎，為月；離為日。日月麗天也。</p><p>虞翻曰：震為百穀，巽為草木，坤為地。乾二五之坤成坎。震體屯。屯者，盈也。盈天地之間者唯萬物，萬物出震，故百穀草木麗乎土。</p><p>虞翻曰：兩象，故重明。正謂五陽。陽變之坤來化乾，以成萬物，謂離日化成天下也。</p><p>虞翻曰：柔謂五陰，中正謂五伏陽。出在坤中，畜牝牛。故中正而亨也。</p><p>荀爽曰：牛者，土也。生土於火。離者，陰卦。牝者，陰性，故曰畜牝牛吉矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：明兩作離，大人以繼明照於四方。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：兩謂日與月也。乾五之坤成坎，坤二之乾成離，離坎日月之象，故明兩作離。作，成也。日月在天，動成萬物，故稱作矣。或以日與火為明。兩作也。</p><p>虞翻曰：陽氣稱大人，則乾五大人也。乾二五之光，繼日之明。坤為方，二五之坤。震東兌西，離南坎北，故曰照於四方。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，履錯然，敬之，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>荀爽曰：火性炎上，故初欲履錯於三。二為三所據。故敬之則無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：履錯之敬，以闢咎也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：錯然，敬慎之貌也。處離之始，將進其盛，故宜慎所履。以敬為務，闢其咎也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，黃離，元吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：黃離元吉，得中道也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：此本坤爻，故雲黃離。來得中道，所以元吉也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，日昃之離，不鼓缶而歌，則大耋之嗟，兇。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：初為日出，二為日中，三為日昃，以喻君道衰也。</p><p>《九家易》曰：鼓缶者以目下視。離為大腹，瓦缶之象，謂不取二也。歌者口仰向上，謂兌為口，而向上取五也。日昃者，向下也。今不取二，而上取五，則上九耋之陽稱大也。嗟者，謂上被三奪五，憂嗟窮兇也。火性炎上，故三欲取五也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：日昃之離，何可久也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：日昃當降，何可久長。三當據二，以為鼓缶，而今與四同取於五，故曰不鼓缶而歌也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，突如其來如，焚如，死如，棄如。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>荀爽曰：陽升居五，光炎宣揚，故突如也。陰退居四，灰炭降墜，故其來如也。陰以不正，居尊乘陽。歷盡數終，天命所誅。位喪民畔，下離所害。故焚如也。以離入坎，故死如也。火息灰損，故棄如也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：突如其來如，無所容也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：在五見奪，在四見棄，故無所容也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，出涕沱若，戚嗟若，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>荀爽曰：六五陰柔，退居於四，出離為坎，故出涕沱若而下，以順陰陽也。</p><p>虞翻曰：坎為心，震為聲，兌為口，故戚嗟若。動而得正，尊麗陽，故吉也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五之吉，離王公也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：戚嗟順陽，附麗於五，故曰離王公也。陽當居五，陰退還四，五當為王。三則三公也。四處其中，附上下矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，王用出徵，有嘉折首，獲匪其醜，無咎。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：王謂乾。乾二五之坤成坎，體師象；震為出，故王用出徵。首謂坤二五來折乾，故有嘉折首。醜，類也。乾徵得坤陰類，乾陽物，故｢獲非其醜，無咎｣矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：王用出徵，以正邦也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：乾五齣徵坤，故正邦也。</p>',72)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
